package com.bank.retry.dep;

import java.util.concurrent.atomic.AtomicLong;

// Deepest dependency. Counts EVERY attempt so we can measure amplification.
public class Ledger {
    private final AtomicLong attempts = new AtomicLong();
    private final boolean failing;
    public Ledger(boolean failing) { this.failing = failing; }
    public void settle(String transferId) {
        attempts.incrementAndGet();               // every call counts
        if (failing) throw new RuntimeException("Ledger slow/unavailable");
    }
    public long attempts() { return attempts.get(); }
}
