package com.bank.retry.layer;

import java.util.function.Consumer;

// A layer that retries up to maxAttempts. If several of these nest, retries MULTIPLY.
public class RetryingCaller {
    private final int maxAttempts;
    public RetryingCaller(int maxAttempts) { this.maxAttempts = maxAttempts; }
    public void call(String id, Consumer<String> downstream) {
        RuntimeException last = null;
        for (int i = 0; i < maxAttempts; i++) {   // each attempt re-runs the ENTIRE downstream
            try { downstream.accept(id); return; }
            catch (RuntimeException e) { last = e; }
        }
        if (last != null) throw last;
    }
}
