package com.bank.retry.budget;

import java.util.concurrent.atomic.AtomicLong;

// Global cap: even the edge stops retrying once the budget is spent.
public class RetryBudget {
    private final double maxFraction;
    private final AtomicLong requests = new AtomicLong();
    private final AtomicLong retries = new AtomicLong();
    public RetryBudget(double maxFraction) { this.maxFraction = maxFraction; }
    public void recordRequest() { requests.incrementAndGet(); }
    public boolean allowRetry() {
            if (retries.get() < requests.get() * maxFraction) { retries.incrementAndGet();
            return true; }
        return false;                             // budget spent → stop retrying
    }
}
