package com.bank.retry;

import com.bank.retry.budget.RetryBudget;
import com.bank.retry.dep.Ledger;
import com.bank.retry.layer.FailFastCaller;
import com.bank.retry.layer.RetryingCaller;
import java.util.logging.*;

public class RetryAmplificationDemo {
    private static final Logger log = Logger.getLogger(RetryAmplificationDemo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h); log.setLevel(Level.INFO);
    }
    public static void main(String[] args) {
        // ── NAIVE: three layers, each retries 3× → multiply to 27 ──
        Ledger naiveLedger = new Ledger(true);
        RetryingCaller a = new RetryingCaller(3); // gateway
        RetryingCaller b = new RetryingCaller(3); // transfer service
        RetryingCaller c = new RetryingCaller(3); // ledger client
        try {
            a.call("TRF-1", idA ->
                b.call(idA, idB ->
                    c.call(idB, naiveLedger::settle)));   // 3 × 3 × 3
        } catch (RuntimeException ignored) {}
        log.warning(() -> "NAIVE: 1 request → " + naiveLedger.attempts() + " ledger attempts (3×3×3)");

        // ── FIXED: retry ONLY at the edge, inner layers fail fast, global budget ──
        Ledger fixedLedger = new Ledger(true);
        RetryBudget budget = new RetryBudget(0.1);
        budget.recordRequest();
        RetryingCaller edge = new RetryingCaller(3);
        FailFastCaller inner1 = new FailFastCaller();
        FailFastCaller inner2 = new FailFastCaller();
        try {
            edge.call("TRF-2", idA -> {
                if (!budget.allowRetry() && fixedLedger.attempts() > 0) throw new RuntimeException("budget spent");
                inner1.call(idA, idB -> inner2.call(idB, fixedLedger::settle)); // 1 × 1 downstream
            });
        } catch (RuntimeException ignored) {}
        log.info(() -> "FIXED: 1 request → " + fixedLedger.attempts()
                + " ledger attempts (edge-only + budget)");
        log.info(() -> "Amplification cut from " + naiveLedger.attempts()
                + "x to " + fixedLedger.attempts() + "x");
    }
}

